/**
 * The shared game catalogue: `public/games.json`, generated by
 * `npm run build:games`.
 *
 * The desktop page shows it in a dialog and the phone layout shows it as a
 * dashboard, so loading and identifying an entry live here rather than in
 * either page.
 */

export interface GameEntry {
  name: string;
  url: string;
}

/**
 * Identifier of a game in a URL (`/m/play?game=…`).
 *
 * The names in the list are unique — they come from the file names of a single
 * flat directory — so the name doubles as the id: it stays readable in a shared
 * link, and the entry can be looked up without remembering an index.
 */
export function gameId(game: GameEntry): string {
  return game.name;
}

export function findGame(games: readonly GameEntry[], id: string): GameEntry | undefined {
  return games.find((game) => gameId(game) === id);
}

const LIST_URL = `${import.meta.env.BASE_URL}games.json`;

/** In-flight or settled fetch, shared by every caller in the page. */
let pending: Promise<GameEntry[]> | null = null;

/**
 * Fetch the catalogue (about 140 KB) once per page load.
 *
 * The desktop dialog is opened and closed repeatedly, and the phone layout
 * needs the same data one navigation later, so the promise is memoised instead
 * of refetched. A failure is not cached: the next caller gets a fresh attempt.
 */
export function loadGameList(): Promise<GameEntry[]> {
  if (!pending) {
    pending = fetch(LIST_URL)
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json() as Promise<GameEntry[]>;
      })
      .catch((cause: unknown) => {
        pending = null;
        throw cause;
      });
  }
  return pending;
}
